typedef float vm_num_t;

class stringx
{
public:
  stringx operator+(const char*) const;
};

stringx operator+(const char*, const stringx&);
void error(const stringx&);

class script_object
{
public:
  const stringx& get_name() const;
};

class vm_executable
{
public:
  const stringx& get_fullname() const;
};

class vm_thread
{
public:
  script_object* get_instance() const;
  vm_executable* get_executable() const;
};

class vm_stack
{
public:
  char* SP;
  vm_thread* my_thread;

  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

struct vm_vector3d_list_iterator_t
{
  void* current;

  bool operator==(const vm_vector3d_list_iterator_t& other) const
  {
    return current == other.current;
  }
};

class slf_vector3d_list_iterator_is_equal_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_vector3d_list_iterator_t me;
    vm_vector3d_list_iterator_t you;
  };

  virtual bool operator()(vm_stack& stack, entry_t entry);
};

bool slf_vector3d_list_iterator_is_equal_t::operator()(vm_stack& stack, entry_t entry)
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();
  vm_num_t result = parms->me==parms->you;
  if (!stack.push((char*)&result,sizeof(result)) )
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
  return true;
}
